"""Naive independent reference model for replay mode."""
import struct

def classify(fi, enabled, hdr):
    if not enabled:
        return 'ip','disabled'
    for i,c in enumerate(fi['kinds']):
        if c=='K' and hdr[i]!=fi['tmpl'][i]:
            return 'ip','mismatch'
    if hdr[fi['qoff']]>7:
        return 'ip','qos'
    return 'mpls','compressed'

def packet(fi, enabled, hdr, pay):
    N=len(fi['path']); h=N-1
    mode,reason = classify(fi, enabled, hdr)
    qoff=fi['qoff']; toff=fi['toff']
    q=hdr[qoff]; ttl=hdr[toff]
    wire=[]
    ok = mode=='mpls'
    residue=bytes(hdr[i] for i,c in enumerate(fi['kinds']) if c=='D')
    t=ttl
    emitted=0
    for i in range(N):
        if t<=0: break
        if ok:
            word=(fi['labels'][i]<<12)|(q<<9)|(1<<8)|t
            link=struct.pack('>I',word)+residue+pay
        else:
            nb=bytearray(hdr); nb[toff]=t
            link=bytes(nb)+pay
        wire.append(link.hex())
        emitted+=1
        if i<N-1:
            if t<=1: break
            t-=1
    if emitted==N:
        if ok:
            vec=bytearray(N*0 + fi['H'])
            for i,c in enumerate(fi['kinds']):
                if c=='K': vec[i]=fi['tmpl'][i]
                elif c=='Z': vec[i]=0
                elif c=='Q': vec[i]=q
                elif c=='T': vec[i]=t
            j=0
            for i,c in enumerate(fi['kinds']):
                if c=='D':
                    vec[i]=residue[j]; j+=1
            delivered=(bytes(vec)+pay).hex()
        else:
            delivered=wire[-1]
    else:
        delivered=None
    return dict(mode=mode,reason=reason,wire=wire,delivered=delivered,
                byte_hops=sum(len(w)//2 for w in wire))

def run(req):
    flows={f['id']:dict(id=f['id'],path=f['path'],kinds=f['kinds'],
        tmpl=bytes.fromhex(f['template']),labels=f['labels'],
        H=len(bytes.fromhex(f['template'])),
        qoff=f['kinds'].index('Q'),toff=f['kinds'].index('T')) for f in req['flows']}
    caps=req['capacities']
    tables={n:{} for n in caps}
    enabled=set()
    results=[]
    for ev in req['events']:
        op=ev['op']
        if op=='put':
            fi=flows[ev['flow']]; node=ev['node']
            label=fi['labels'][fi['path'].index(node)]
            tb=tables[node]
            cur=tb.get(label)
            if cur==ev['flow']: results.append({'status':'ok'})
            elif cur is not None and cur in enabled: results.append({'status':'busy'})
            elif label not in tb and len(tb)>=caps[node]: results.append({'status':'full'})
            else: tb[label]=ev['flow']; results.append({'status':'ok'})
        elif op=='enable':
            fid=ev['flow']; fi=flows[fid]
            if fid in enabled: results.append({'status':'ok'}); continue
            ready=all(tables[fi['path'][i]].get(fi['labels'][i])==fid for i in range(len(fi['path'])))
            if ready: enabled.add(fid); results.append({'status':'ok'})
            else: results.append({'status':'unready'})
        elif op=='disable':
            enabled.discard(ev['flow']); results.append({'status':'ok'})
        elif op=='reset':
            enabled.clear(); results.append({'status':'ok'})
        elif op=='packet':
            fi=flows[ev['flow']]
            results.append(packet(fi, ev['flow'] in enabled,
                bytes.fromhex(ev['header']), bytes.fromhex(ev['payload'])))
        else:
            raise AssertionError('op')
    tbl=[]
    for n in sorted(tables):
        for l in sorted(tables[n]):
            tbl.append({'node':n,'label':l,'flow':tables[n][l]})
    return {'results':results,'active':sorted(enabled),'tables':tbl}
