import random, json, sys
sys.path.insert(0,'/workspace/dev')
import ref_replay
sys.path.insert(0,'/workspace/submission')
import importlib.util
spec=importlib.util.spec_from_file_location('m','/workspace/submission/main.py')
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

def gen(rng, nflows=None, ncap=None, nevents=None):
    nnodes = rng.randint(1,5)
    nodes=['s%d'%i for i in range(nnodes)]
    caps=dict((n, rng.choice([0,1,1,2,2,3,512])) for n in nodes)
    nflows = nflows if nflows is not None else rng.randint(0,5)
    flows=[]; ids=[]
    for i in range(nflows):
        fid=rng.choice(['f','flow.%d','%s_%d'%(rng.choice(['a','b']),i),'X-%d'%i])+str(i)
        while fid in ids: fid=fid+'x'
        ids.append(fid)
        k=rng.randint(2,len(nodes)) if len(nodes)>=2 else 2
        if len(nodes)<2:
            nodes2=nodes+['extra']
            caps['extra']=rng.randint(0,3); nodes=nodes2
            k=rng.randint(2,len(nodes))
        path=rng.sample(nodes,k)
        H=rng.randint(8,30)
        nd=rng.randint(0,H-5)
        kinds=['D']*nd+['Q','T']
        nk=H-len(kinds)
        kinds+=['K']*nk
        rng.shuffle(kinds)
        tmpl=bytes(rng.randint(0,255) for _ in range(H))
        labels=[rng.choice([16,17,rng.randint(16,1048575)]) for _ in path]
        flows.append(dict(id=fid,path=path,template=tmpl.hex(),kinds=''.join(kinds),labels=labels))
    nevents = nevents if nevents is not None else rng.randint(0,25)
    events=[]
    for _ in range(nevents):
        if not flows:
            events.append(dict(op='reset')); continue
        r=rng.random()
        f=rng.choice(flows)
        if r<0.35:
            events.append(dict(op='put',flow=f['id'],node=rng.choice(f['path']+[rng.choice(list(caps))])))
        elif r<0.5:
            events.append(dict(op='enable',flow=f['id']))
        elif r<0.6:
            events.append(dict(op='disable',flow=f['id']))
        elif r<0.65:
            events.append(dict(op='reset'))
        else:
            H=len(f['template'])//2; kinds=f['kinds']
            hdr=bytearray(rng.randint(0,255) for _ in range(H))
            tmpl=bytes.fromhex(f['template'])
            for i,c in enumerate(kinds):
                if c=='K' and rng.random()<0.8: hdr[i]=tmpl[i]
            hdr[kinds.index('Q')]=rng.choice([0,7,8,255,rng.randint(0,7)])
            hdr[kinds.index('T')]=rng.choice([0,1,2,3,255,rng.randint(0,255)])
            paylen=rng.choice([0,1,2,rng.randint(0,300)])
            events.append(dict(op='packet',flow=f['id'],header=hdr.hex(),
                payload=bytes(rng.randint(0,255) for _ in range(paylen)).hex()))
    return dict(mode='replay',capacities=caps,flows=flows,events=events)

rng=random.Random(sys.argv[1] if len(sys.argv)>1 else 3)
bad=0
for t in range(4000):
    req=gen(rng)
    line=json.dumps(req)
    try:
        exp=ref_replay.run(json.loads(line))
    except Exception as e:
        continue
    got=m.respond(json.loads(line))
    if got!=exp:
        print('MISMATCH at',t)
        print(json.dumps(req))
        print('exp',json.dumps(exp))
        print('got',json.dumps(got))
        bad+=1
        if bad>=2: break
print('replay fuzz done, bad =',bad)
